const r = $input.item.json;
const data = r.data || r;
const ts = new Date().toLocaleString('en-US', {timeZone: 'America/Denver', weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit'});

// Pricing changes
const priceChanges = data.pricing_changes || data.price_alerts || [];
let priceBlock = '';
if (priceChanges.length) {
  priceBlock = '*Pricing Changes:*\n' + priceChanges.slice(0,5).map(p => `• ${p.cruise_line || p.line} — ${p.change || p.summary}`).join('\n');
} else {
  priceBlock = '*Pricing:* No significant changes detected';
}

// New itineraries
const newItin = data.new_itineraries || data.itinerary_launches || [];
let itinBlock = '';
if (newItin.length) {
  itinBlock = '\n\n*New Itineraries:*\n' + newItin.slice(0,5).map(i => `• ${i.cruise_line || i.line}: ${i.name || i.itinerary} (${i.dates || i.season || ''})`).join('\n');
}

// Summary stats
const lines = data.lines_monitored || data.cruise_lines_checked || 0;
const statsLine = lines ? `\n\n_${lines} cruise lines monitored_` : '';

// Key findings
const findings = data.key_findings || data.highlights || [];
let findingsBlock = '';
if (findings.length) {
  findingsBlock = '\n\n*Key Findings:*\n' + findings.slice(0,3).map(f => `• ${f}`).join('\n');
}

const message = `*D2M Competitive Intel — ${ts}*\n\n${priceBlock}${itinBlock}${findingsBlock}${statsLine}`;
return [{ json: { message } }];
